CREATE FUNCTION public.validate_client_program() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE e jsonb; mark integer; BEGIN IF jsonb_typeof(new.definition) IS DISTINCT FROM 'object' OR length(trim(coalesce(new.definition->>'name',''))) NOT BETWEEN 1 AND 100 OR jsonb_typeof(new.definition->'exercises') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid program'; END IF; IF jsonb_array_length(new.definition->'exercises')<1 THEN RAISE EXCEPTION 'Add at least one exercise'; END IF; FOR e IN SELECT * FROM jsonb_array_elements(new.definition->'exercises') LOOP IF length(trim(coalesce(e->>'name',''))) NOT BETWEEN 1 AND 100 OR jsonb_typeof(e->'sets') IS DISTINCT FROM 'number' OR (e->>'sets')::numeric != trunc((e->>'sets')::numeric) OR (e->>'sets')::numeric NOT BETWEEN 1 AND 100 OR length(trim(coalesce(e->>'reps',''))) NOT BETWEEN 1 AND 30 OR length(coalesce(e->>'image',''))>8000 THEN RAISE EXCEPTION 'Invalid exercise'; END IF; END LOOP; FOREACH mark IN ARRAY new.completion LOOP IF mark<0 OR mark>=jsonb_array_length(new.definition->'exercises') THEN RAISE EXCEPTION 'Invalid completion mark'; END IF; END LOOP; RETURN new; END $$;
CREATE TRIGGER validate_personal_program BEFORE INSERT OR UPDATE ON public.client_programs FOR EACH ROW EXECUTE FUNCTION public.validate_client_program();